<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { AuditResponseSchema, SecretsResponseSchema, ManagementSessionSchema } from '../../../../packages/contracts/src/operator';
import { runtimeRequest, runtimeAction, downloadRuntimeFile } from '../../api/typescript';
import { confirmDestructiveAction, useUnsavedDraft } from '../../composables/unsaved';
const tab = ref<'credentials'|'audit'>('credentials'); const busy = ref(false); const error = ref(''); const notice = ref(''); const secretName = ref(''); const secretValue = ref(''); const secrets = ref<ReturnType<typeof SecretsResponseSchema.parse>['secrets']>([]); const records = ref<ReturnType<typeof AuditResponseSchema.parse>['records']>([]); const expiresAt = ref<number>();
const { dirty, markSaved, confirmDiscard } = useUnsavedDraft('服务端密钥', () => ({ name: secretName.value, value: secretValue.value }));
function clearDraft() { secretName.value = ''; secretValue.value = ''; markSaved(); }
function switchTab(next: 'credentials' | 'audit') { if (busy.value || tab.value === next || !confirmDiscard()) return; clearDraft(); tab.value = next; if (next === 'audit') void perform(refresh); }
function replaceSecret(name: string) { if (busy.value || !confirmDiscard()) return; clearDraft(); secretName.value = name; notice.value = `正在替换 ${name}，输入新值后保存。`; }
async function perform(operation: () => Promise<void>) { if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await operation();}catch(cause){error.value=cause instanceof Error?cause.message:String(cause);}finally{busy.value=false;} }
async function refresh() { secrets.value=(await runtimeRequest('management/secrets',SecretsResponseSchema)).secrets; records.value=(await runtimeRequest('management/audit',AuditResponseSchema)).records; const session=await runtimeRequest('auth/session',ManagementSessionSchema);expiresAt.value=session.expiresAt; }
async function saveSecret() { if (busy.value) return; const name = secretName.value.trim(); if (secrets.value.some(secret => secret.name === name) && !confirmDestructiveAction(`替换密钥 ${name}？受影响的机器人连接将重新读取凭据，旧值无法查看或恢复。`)) return; await perform(async()=>{ await runtimeAction(`management/secrets/${encodeURIComponent(secretName.value.trim())}`,{value:secretValue.value},'PUT');clearDraft(); await refresh();notice.value='密钥已保存，受影响的机器人连接会重新读取凭据。'; }); }
async function deleteSecret(name: string) { if (busy.value || !confirmDiscard() || !confirmDestructiveAction(`移除密钥 ${name}？旧值无法恢复；移除后会回退到同名环境变量（若存在）。`)) return; await perform(async()=>{await runtimeAction(`management/secrets/${encodeURIComponent(name)}`,undefined,'DELETE'); clearDraft(); await refresh(); notice.value = `密钥 ${name} 已移除。`; }); }
function time(value:number):string{return new Date(value).toLocaleString();}
onMounted(()=>{void perform(async () => { await refresh(); markSaved(); });});
</script>
<template>
<section class="ts-fields"><nav class="ts-tabs" aria-label="管理设置"><button :class="{active:tab==='credentials'}" :disabled="busy" @click="switchTab('credentials')">登录与密钥</button><button :class="{active:tab==='audit'}" :disabled="busy" @click="switchTab('audit')">操作日志</button></nav>
<p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="notice" class="notice ok" role="status">{{notice}}</p>
<template v-if="tab==='credentials'"><div class="card"><h3>管理登录</h3><p>{{expiresAt?`登录有效至 ${time(expiresAt)}，刷新页面会自动恢复。`:'当前使用管理令牌连接。'}}</p><p class="muted">使用浏览器 HttpOnly 会话，退出后立即失效。管理令牌不写入浏览器存储。</p></div><div class="section-title"><div><h2>服务端密钥</h2><p>填写名称后，在机器人或模型设置中引用。密钥只写入，不会回显或包含在配置导出中。</p></div><button :disabled="busy" @click="perform(refresh)">刷新</button></div><form class="ts-fields" @submit.prevent="saveSecret"><p class="muted" role="status">独立保存 · {{ dirty ? '密钥草稿未保存' : '填写密钥后保存' }}。保存后服务端立即读取；刷新列表会保留正在输入的内容。</p><fieldset :disabled="busy" class="secret-fields"><div class="ts-form-grid"><label>密钥名称<input v-model="secretName" required pattern="[A-Z_][A-Z0-9_]*" placeholder="TELEGRAM_TOKEN" autocomplete="off"></label><label>密钥值<input v-model="secretValue" required type="password" autocomplete="new-password"></label></div><button class="primary" :disabled="busy || !secretName.trim() || !secretValue">{{ busy ? '处理中…' : '保存密钥' }}</button></fieldset></form><p class="muted">保存在当前本机运行数据库中，优先于同名环境变量；数据库备份应按敏感文件保管。</p><div class="table-wrap"><table class="table"><thead><tr><th>名称</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="secret in secrets" :key="secret.name"><td>{{secret.name}}</td><td>{{time(secret.updatedAt)}}</td><td><button :disabled="busy" @click="replaceSecret(secret.name)">替换密钥</button><button class="danger" :disabled="busy" @click="deleteSecret(secret.name)">删除密钥</button></td></tr></tbody></table></div><p v-if="!secrets.length" class="empty-state">未保存额外密钥。现有环境变量凭据仍可正常使用。</p><button :disabled="busy" @click="perform(()=>downloadRuntimeFile('management/export','priestess-configuration.json'))">导出当前配置（不含密钥）</button></template>
<template v-else><div class="section-title"><div><h2>管理操作日志</h2><p>保留最近 2000 条管理操作，不记录请求正文或密钥值。</p></div><button :disabled="busy" @click="perform(refresh)">刷新日志</button></div><div class="table-wrap"><table class="table"><thead><tr><th>时间</th><th>操作</th><th>目标</th><th>结果</th></tr></thead><tbody><tr v-for="record in records" :key="record.id"><td>{{time(record.timestamp)}}</td><td>{{record.action}}</td><td>{{record.target}}</td><td>{{record.outcome==='success'?'成功':'失败'}}</td></tr></tbody></table></div><p v-if="!records.length" class="empty-state">暂无管理操作。</p></template></section>
</template>

<style scoped>.secret-fields{display:grid;gap:16px;border:0;padding:0;margin:0;min-width:0}</style>
